import numpy as np

def solve(data):
    grid = data['grid']

    # Convert list of lists to numpy array for efficient computation
    grid_np = np.array(grid)

    # Initialize the grid with infinity except for the starting point
    dp = np.full_like(grid_np, np.inf)
    dp[0, 0] = 0

    # Fill the DP table
    for i in range(1, len(grid)):
        dp[i, 0] += grid_np[i, 0]
    for j in range(1, len(grid[0])):
        dp[0, j] += grid_np[0, j]
    for i in range(1, len(grid)):
        for j in range(1, len(grid[0])):
            dp[i, j] = min(dp[i - 1, j], dp[i, j - 1]) + grid_np[i, j]

    # If the bottom-right corner is still infinity, there is no valid path
    if dp[-1, -1] == np.inf:
        return None

    return dp[-1, -1]

import math

def solve(data):
    grid = data["grid"]

    # Check for empty or minimal inputs
    if not grid or len(grid) == 0 or len(grid[0]) == 0:
        return None

    # Initialize the DP table with infinity
    dp = [[math.inf] * len(grid[0]) for _ in range(len(grid))]

    # Set the starting point
    dp[0][0] = grid[0][0]

    # Fill the DP table
    for i in range(1, len(grid)):
        dp[i][0] = dp[i-1][0] + grid[i][0]
    for j in range(1, len(grid[0])):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    for i in range(1, len(grid)):
        for j in range(1, len(grid[0])):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # If the destination is unreachable, return None
    if dp[-1][-1] == math.inf:
        return None

    return dp[-1][-1]

